template <int N>
struct Factorial {
    static const int value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
    static const int value = 1;
};

// Usage: Factorial<5>::value == 120

// --- Compile-Time Type Selection based on computation ---

template<typename T, typename U>
struct MaxType {
    using type = std::conditional_t<
        (sizeof(T) >= sizeof(U)), T, U
    >;
};

// Usage: MaxType<char, int>::type var; // var is type int
// The choice is determined at compile time.
